SELECT result.c0 AS "region", result.c1 AS "n", result.c2 AS "total" FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2 FROM (SELECT t.c0 AS c0, CAST(COUNT(*) AS BIGINT) AS c1, CAST(SUM(t.c1) AS BIGINT) AS c2 FROM (SELECT t.c4 AS c0, t.c2 AS c1 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, r.c0 AS c3, r.c1 AS c4 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2 FROM (SELECT "id" AS c0, "ts" AS c1, "amount" AS c2 FROM "events") t WHERE (t.c2 > 0)) l JOIN (SELECT "id" AS c0, "region" AS c1 FROM "accounts") r ON (l.c0 = r.c0)) t) t GROUP BY t.c0) t) result;
